def transform(grid):
    h, w = len(grid), len(grid[0])
    out = []
    # Reflect the grid into a 3-by-2 arrangement: vertical orientation alternates,
    # and the left tile is horizontally reflected.
    for tile_y in range(3):
        rows = grid[::-1] if tile_y % 2 == 0 else grid
        for row in rows:
            out.append(row[::-1] + row[:])
    return out
